import SwiftUI

/// One open-source component and its license text (generated by scripts/gen_acknowledgements.py).
struct Acknowledgement: Decodable, Identifiable, Hashable {
    var id: String { name }
    let name: String
    let url: String
    let license: String
    let text: String

    static let all: [Acknowledgement] = {
        guard let url = Bundle.main.url(forResource: "Acknowledgements", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let list = try? JSONDecoder().decode([Acknowledgement].self, from: data) else { return [] }
        return list
    }()
}

struct LicensesView: View {
    var body: some View {
        List {
            Section {
                ForEach(Acknowledgement.all) { item in
                    NavigationLink {
                        LicenseDetailView(item: item)
                    } label: {
                        LabeledContent(item.name, value: item.license)
                    }
                }
            } footer: {
                Text("PocketCode is built on these open-source projects. Thank you to their authors.")
            }
        }
        .navigationTitle("Open Source Licenses")
        .navigationBarTitleDisplayMode(.inline)
    }
}

struct LicenseDetailView: View {
    let item: Acknowledgement
    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 12) {
                if let url = URL(string: item.url) {
                    Link(item.url, destination: url).font(.footnote)
                }
                Text(item.text)
                    .font(.system(size: 11, design: .monospaced))
                    .foregroundStyle(.secondary)
                    .textSelection(.enabled)
            }
            .padding()
            .frame(maxWidth: .infinity, alignment: .leading)
        }
        .navigationTitle(item.name)
        .navigationBarTitleDisplayMode(.inline)
    }
}
